/**
 * react-refresh glue for mdx modules. Same job as rspack's
 * builtin:react-refresh-loader, but written for ESM.
 *
 * The builtin loader's glue says `module.hot` / `module.id`. MDX compiles to
 * strict ESM, and ESM has no `module` — that glue crashes with
 * "module is not defined". So we say the same things the ESM way:
 * - `import.meta.webpackHot`  instead of `module.hot`
 * - `__webpack_module__.id`   instead of `module.id`
 * - `$ReactRefreshRuntime$` — the refresh plugin provides it in any module.
 *
 * The id must be the REAL module id. The refresh runtime uses it to find the
 * module in webpack's cache — a made-up id (like the file path) makes it warn
 * "Failed to get exports for module" and the module never hot-swaps.
 *
 * The header goes above the source so the $RefreshReg$/$RefreshSig$ calls
 * babel injected into the body can find these bindings (imports hoist above
 * both, so order stays correct).
 */
module.exports = function reactRefreshMdxLoader(source) {
  const header = `var $RefreshReg$ = function (type, refreshId) { $ReactRefreshRuntime$.register(type, __webpack_module__.id + "_" + refreshId) };
var $RefreshSig$ = function () { return $ReactRefreshRuntime$.createSignatureFunctionForTransform() };
`;
  const footer = `
if (import.meta.webpackHot) {
  Promise.resolve().then(function () { $ReactRefreshRuntime$.refresh(__webpack_module__.id, import.meta.webpackHot) });
}
`;
  return header + source + footer;
};
